package com.citygo;
import com.citygo.fulfillment.service.*;
import com.citygo.fulfillment.mapper.FulfillmentMapper;
import com.citygo.booking.service.BookingService;
import com.citygo.payment.service.PaymentService;
import com.citygo.common.exception.BizException;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.Import;
import org.springframework.test.context.bean.override.mockito.MockitoSpyBean;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import static org.springframework.http.MediaType.APPLICATION_JSON;
@Import(PaymentLifecycleIntegrationTest.TimeConfig.class) class FulfillmentIntegrationTest extends P2Fixtures {
 @Autowired PaymentLifecycleIntegrationTest.MutableTime time;@Autowired BookingService booking;@Autowired PaymentService payments;@Autowired ScheduleService schedules;@Autowired CheckinService checkins;@MockitoSpyBean FulfillmentMapper f;
 @Autowired com.citygo.notification.service.OutboxWorker worker;
 long uid,other,actor,source,target,order,contact;String token,staffToken;
 @BeforeEach void fixture()throws Exception{time.current=Instant.now().truncatedTo(java.time.temporal.ChronoUnit.MILLIS);uid=insertUser("scheduleuser","secret123","USER",true);other=insertUser("scheduleother","secret123","USER",true);actor=insertUser("scheduleop","secret123","OPERATOR",true);token=loginToken("scheduleuser","secret123");staffToken=loginToken("scheduleop","secret123");source=session(3,1000);target=sibling(20,3,1000);contact=contact(uid);order=create("schedule-original");}
 long create(String key){long id=booking.create(uid,key,request(contact,line("SESSION",source,1))).order().id();payments.pay(uid,id,"SUCCESS");payments.confirm(actor,id);return id;}
 long sibling(int days,int capacity,int price){Long aid=jdbcTemplate.queryForObject("SELECT activity_id FROM sessions WHERE id=?",Long.class,source);var start=LocalDateTime.now(time).plusDays(days);jdbcTemplate.update("INSERT INTO sessions(activity_id,start_time,end_time,booking_deadline,price_cents,capacity,available,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,'ON_SALE',?,?)",aid,start,start.plusHours(2),start.minusDays(1),price,capacity,capacity,LocalDateTime.now(time),LocalDateTime.now(time));return jdbcTemplate.queryForObject("SELECT MAX(id) FROM sessions",Long.class);}
 ScheduleService.Request move(long target,int version){return new ScheduleService.Request(target,version);}
 int code(Runnable r){try{r.run();return 0;}catch(BizException e){return e.getErrorCode().getCode();}}
 @Test void reschedulePreservesOriginalSnapshotAndPriceAndMovesOnlyCurrentAllocation(){String original=jdbcTemplate.queryForObject("SELECT session_snapshot FROM order_items WHERE order_id=?",String.class,order);var v=schedules.reschedule(uid,order,"reschedule-first",move(target,0));assertThat(v.version()).isEqualTo(1);assertThat(v.current().path("sessionId").asLong()).isEqualTo(target);assertThat(stock(source)).isEqualTo(3);assertThat(stock(target)).isEqualTo(2);assertThat(jdbcTemplate.queryForObject("SELECT session_snapshot FROM order_items WHERE order_id=?",String.class,order)).isEqualTo(original);assertThat(jdbcTemplate.queryForObject("SELECT total_cents FROM orders WHERE id=?",Integer.class,order)).isEqualTo(1000);assertThat(jdbcTemplate.queryForObject("SELECT session_id FROM order_allocations WHERE order_id=?",Long.class,order)).isEqualTo(target);assertThat(v.history()).hasSize(1);}
 @Test void retryKeyIsBoundToTargetAndExpectedVersion(){schedules.reschedule(uid,order,"reschedule-retry",move(target,0));schedules.reschedule(uid,order,"reschedule-retry",move(target,0));assertThat(f.history(order)).hasSize(1);assertThat(code(()->schedules.reschedule(uid,order,"reschedule-retry",move(source,0)))).isEqualTo(40913);assertThat(code(()->schedules.reschedule(uid,order,"reschedule-stale",move(source,0)))).isEqualTo(40900);assertThat(stock(target)).isEqualTo(2);}
 @Test void insufficientTargetLeavesOriginalBookingUntouched(){jdbcTemplate.update("UPDATE sessions SET available=0 WHERE id=?",target);assertThat(code(()->schedules.reschedule(uid,order,"reschedule-full",move(target,0)))).isEqualTo(40903);assertThat(stock(source)).isEqualTo(2);assertThat(f.version(order)).isZero();assertThat(f.history(order)).isEmpty();}
 @Test void differentActivityAndPriceAreRejected(){long another=session(3,1000),priced=sibling(25,3,2000);assertThat(code(()->schedules.reschedule(uid,order,"reschedule-other",move(another,0)))).isEqualTo(40900);assertThat(code(()->schedules.reschedule(uid,order,"reschedule-price",move(priced,0)))).isEqualTo(40900);assertThat(stock(source)).isEqualTo(2);}
 @Test void disabledTargetOrPlatformCannotReceiveReschedule(){jdbcTemplate.update("UPDATE sessions SET status='OFF_SALE' WHERE id=?",target);assertThat(code(()->schedules.reschedule(uid,order,"reschedule-offline",move(target,0)))).isEqualTo(40904);jdbcTemplate.update("UPDATE sessions SET status='ON_SALE' WHERE id=?",target);jdbcTemplate.update("UPDATE platform_settings SET setting_value='false' WHERE setting_key='accepting_orders'");assertThat(code(()->schedules.reschedule(uid,order,"reschedule-paused",move(target,0)))).isEqualTo(40906);}
 @Test void originalStartAndUnsupportedOrdersHaveExplicitRules(){time.advance(Duration.ofDays(10));assertThat(schedules.view(uid,order).canReschedule()).isFalse();assertThat(code(()->schedules.reschedule(uid,order,"reschedule-started",move(target,0)))).isEqualTo(40900);time.current=Instant.now().truncatedTo(java.time.temporal.ChronoUnit.MILLIS);long pack=pkg(1000,source);long po=booking.create(uid,"reschedule-package",request(contact,line("PACKAGE",pack,1))).order().id();payments.pay(uid,po,"SUCCESS");payments.confirm(actor,po);assertThat(schedules.view(uid,po).canReschedule()).isFalse();assertThat(code(()->schedules.reschedule(uid,po,"reschedule-pack",move(target,0)))).isEqualTo(40900);}
 @Test void failureAfterInventoryMutationRollsEverythingBack(){doThrow(new IllegalStateException("rollback injection")).when(f).saveCurrent(anyLong(),anyLong(),anyString(),anyInt(),any());assertThatThrownBy(()->schedules.reschedule(uid,order,"reschedule-rollback",move(target,0))).isInstanceOf(IllegalStateException.class);assertThat(stock(source)).isEqualTo(2);assertThat(stock(target)).isEqualTo(3);assertThat(f.version(order)).isZero();assertThat(f.history(order)).isEmpty();}
 @Test void refundAfterMoveReleasesOnlyNewSession(){schedules.reschedule(uid,order,"reschedule-refund",move(target,0));payments.refund(uid,order,"模拟退款");payments.refund(uid,order,"重试");assertThat(stock(source)).isEqualTo(3);assertThat(stock(target)).isEqualTo(3);assertThat(count("refunds")).isEqualTo(1);}
 @Test void refundAndCompletionUseNewTimeButKeepHistoricalSnapshot(){schedules.reschedule(uid,order,"reschedule-new-time",move(target,0));time.advance(Duration.ofDays(11));assertThat(code(()->payments.complete(actor,order))).isEqualTo(40911);time.advance(Duration.ofDays(10));payments.complete(actor,order);assertThat(stock(target)).isEqualTo(2);assertThat(f.checkin(order).source()).isEqualTo("MANUAL");assertThat(f.checkin(order).operatorId()).isEqualTo(actor);}
 @Test void canRefundBeforeNewStartEvenAfterOriginalStart(){schedules.reschedule(uid,order,"reschedule-later",move(target,0));time.advance(Duration.ofDays(11));payments.refund(uid,order,"改期后退款");assertThat(stock(source)).isEqualTo(3);assertThat(stock(target)).isEqualTo(3);}
 @Test void twentyOrdersCompeteForLastTargetSeat()throws Exception{jdbcTemplate.update("UPDATE sessions SET capacity=50,available=49 WHERE id=?",source);jdbcTemplate.update("UPDATE sessions SET capacity=1,available=1 WHERE id=?",target);List<Long> ids=new ArrayList<>();ids.add(order);for(int i=1;i<20;i++)ids.add(create("reschedule-race-"+i));AtomicInteger success=new AtomicInteger();var pool=Executors.newFixedThreadPool(20);var start=new CountDownLatch(1);try{List<Future<?>> work=new ArrayList<>();for(Long id:ids)work.add(pool.submit(()->{try{start.await();schedules.reschedule(uid,id,"last-seat-move-"+id,move(target,0));success.incrementAndGet();}catch(BizException e){assertThat(e.getErrorCode().getCode()).isEqualTo(40903);}catch(InterruptedException e){throw new RuntimeException(e);}}));start.countDown();for(var job:work)job.get(30,TimeUnit.SECONDS);}finally{pool.shutdownNow();}assertThat(success.get()).isEqualTo(1);assertThat(stock(target)).isZero();assertThat(stock(source)).isEqualTo(31);assertThat(count("order_reschedules")).isEqualTo(1);assertThat(count("orders")).isEqualTo(20);}
 @Test void concurrentSameKeyMovesOnlyOnce()throws Exception{var pool=Executors.newFixedThreadPool(10);try{List<Callable<Integer>> jobs=new ArrayList<>();for(int i=0;i<10;i++)jobs.add(()->schedules.reschedule(uid,order,"reschedule-same-key",move(target,0)).version());for(var future:pool.invokeAll(jobs))assertThat(future.get()).isEqualTo(1);}finally{pool.shutdownNow();}assertThat(f.history(order)).hasSize(1);assertThat(stock(source)).isEqualTo(3);assertThat(stock(target)).isEqualTo(2);}
 @Test void rescheduleRefundRaceRestoresBothInventories()throws Exception{var pool=Executors.newFixedThreadPool(2);try{var results=pool.invokeAll(List.<Callable<Integer>>of(()->code(()->schedules.reschedule(uid,order,"reschedule-refund-race",move(target,0))),()->code(()->payments.refund(uid,order,"并发退款"))));for(var result:results)assertThat(result.get()).isIn(0,40900);}finally{pool.shutdownNow();}assertThat(stock(source)).isEqualTo(3);assertThat(stock(target)).isEqualTo(3);assertThat(jdbcTemplate.queryForObject("SELECT status FROM orders WHERE id=?",String.class,order)).isEqualTo("REFUNDED");}
 @Test void codeContainsNoContactOrJwtAndDatabaseStoresOnlyHash(){var ticket=checkins.issue(uid,order);assertThat(ticket.code()).startsWith("citygo:checkin:").hasSize("citygo:checkin:".length()+43).doesNotContain("13800000000",token);assertThat(jdbcTemplate.queryForObject("SELECT token_hash FROM checkin_tickets WHERE order_id=?",String.class,order)).hasSize(64).doesNotContain(ticket.code());assertThat(checkins.preview(ticket.code()).canComplete()).isFalse();}
 @Test void expiredAndSupersededCodesAreRejected(){var first=checkins.issue(uid,order);var second=checkins.issue(uid,order);assertThat(code(()->checkins.preview(first.code()))).isEqualTo(40900);time.advance(Duration.ofMinutes(5));assertThat(code(()->checkins.preview(second.code()))).isEqualTo(40900);}
 @Test void rescheduleAndRefundInvalidateCodes(){var old=checkins.issue(uid,order);schedules.reschedule(uid,order,"reschedule-code",move(target,0));assertThat(code(()->checkins.preview(old.code()))).isEqualTo(40900);var fresh=checkins.issue(uid,order);payments.refund(uid,order,"退款失效");assertThat(code(()->checkins.preview(fresh.code()))).isEqualTo(40900);}
 @Test void qrCompletesOnlyOnceAndRecordsOperator(){time.advance(Duration.ofDays(10).plusMinutes(1));var ticket=checkins.issue(uid,order);assertThat(checkins.preview(ticket.code()).canComplete()).isTrue();checkins.redeem(actor,ticket.code());assertThat(f.checkin(order).source()).isEqualTo("QR");assertThat(f.checkin(order).operatorId()).isEqualTo(actor);assertThat(code(()->checkins.redeem(actor,ticket.code()))).isEqualTo(40900);assertThat(count("order_checkins")).isEqualTo(1);assertThat(stock(source)).isEqualTo(2);}
 @Test void concurrentQrRedemptionHasExactlyOneSuccess()throws Exception{time.advance(Duration.ofDays(10).plusMinutes(1));var ticket=checkins.issue(uid,order);var pool=Executors.newFixedThreadPool(10);int success=0;try{List<Callable<Integer>> jobs=new ArrayList<>();for(int i=0;i<20;i++)jobs.add(()->code(()->checkins.redeem(actor,ticket.code())));for(var result:pool.invokeAll(jobs)){int c=result.get();if(c==0)success++;else assertThat(c).isEqualTo(40900);}}finally{pool.shutdownNow();}assertThat(success).isEqualTo(1);assertThat(count("order_checkins")).isEqualTo(1);assertThat(stock(source)).isEqualTo(2);}
 @Test void earlyOrForgedCodeCannotComplete(){var ticket=checkins.issue(uid,order);assertThat(code(()->checkins.redeem(actor,ticket.code()))).isEqualTo(40911);assertThat(code(()->checkins.preview("citygo:checkin:"+"a".repeat(43)))).isEqualTo(40400);assertThat(code(()->checkins.preview("fake"))).isEqualTo(40000);assertThat(count("order_checkins")).isZero();}
 @Test void ownershipAndStaffAuthorizationAreEnforced()throws Exception{assertThat(code(()->checkins.issue(other,order))).isEqualTo(40400);assertThat(code(()->schedules.reschedule(other,order,"reschedule-other-user",move(target,0)))).isEqualTo(40400);var ticket=checkins.issue(uid,order);String body=objectMapper.writeValueAsString(Map.of("code",ticket.code()));mockMvc.perform(post("/api/admin/checkins/preview").header("Authorization",bearer(token)).contentType(APPLICATION_JSON).content(body)).andExpect(status().isForbidden());mockMvc.perform(post("/api/admin/checkins/preview").header("Authorization",bearer(staffToken)).contentType(APPLICATION_JSON).content(body)).andExpect(status().isOk());mockMvc.perform(post("/api/orders/{id}/checkin-code",order).header("Authorization",bearer(staffToken))).andExpect(status().isForbidden());}

 @Test void rescheduleBackToOriginalAndRefundPreservesEverySeat(){schedules.reschedule(uid,order,"reschedule-outbound",move(target,0));schedules.reschedule(uid,order,"reschedule-return",move(source,1));assertThat(f.history(order)).hasSize(2);assertThat(stock(source)).isEqualTo(2);assertThat(stock(target)).isEqualTo(3);payments.refund(uid,order,"往返改期后退款");assertThat(stock(source)).isEqualTo(3);assertThat(stock(target)).isEqualTo(3);}
 @Test void obsoleteReminderIsSuppressedAndNewSessionGetsExactlyOneReminder(){time.advance(Duration.ofDays(10).minusMinutes(30));worker.reminders();schedules.reschedule(uid,order,"reschedule-reminder",move(target,0));worker.drain();assertThat(jdbcTemplate.queryForObject("SELECT COUNT(*) FROM notifications WHERE event_type='ACTIVITY_REMINDER'",Integer.class)).isZero();time.advance(Duration.ofDays(10));worker.reminders();worker.reminders();worker.drain();assertThat(jdbcTemplate.queryForObject("SELECT COUNT(*) FROM notifications WHERE event_type='ACTIVITY_REMINDER'",Integer.class)).isEqualTo(1);assertThat(jdbcTemplate.queryForObject("SELECT COUNT(*) FROM notifications WHERE event_type='ORDER_RESCHEDULED'",Integer.class)).isEqualTo(1);}
 @Test void redeemEndpointAuditsOrderWithoutRecordingSecretCode()throws Exception{time.advance(Duration.ofDays(10).plusMinutes(1));var ticket=checkins.issue(uid,order);String fresh=loginToken("scheduleop","secret123");mockMvc.perform(post("/api/admin/checkins/redeem").header("Authorization",bearer(fresh)).contentType(APPLICATION_JSON).content(objectMapper.writeValueAsString(Map.of("code",ticket.code())))).andExpect(status().isOk());assertThat(f.checkin(order).source()).isEqualTo("QR");assertThat(jdbcTemplate.queryForObject("SELECT target_id FROM audit_logs WHERE action='redeem'",Long.class)).isEqualTo(order);assertThat(jdbcTemplate.queryForObject("SELECT summary FROM audit_logs WHERE action='redeem'",String.class)).doesNotContain(ticket.code());}

}
